package api

import (
    "context"
    "encoding/json"
    "errors"
    "net/http"
)

var ErrNotFound = errors.New("order not found")
type Order struct { ID string `json:"id"` }
type OrderService interface { Get(context.Context, string) (Order, error) }

func GetOrder(svc OrderService) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        id := r.PathValue("id")
        order, err := svc.Get(r.Context(), id)
        if errors.Is(err, ErrNotFound) { WriteProblem(w, 404, "ORDER_NOT_FOUND", "Order not found", ""); return }
        if err != nil { WriteProblem(w, 500, "INTERNAL", "Internal error", ""); return }
        w.Header().Set("Content-Type", "application/json")
        _ = json.NewEncoder(w).Encode(order)
    }
}
